// COM callback objects (CCWs generated by [GeneratedComClass]). They run on audio-service RPC threads, so each one
// copies its arguments and hands them to the engine, which posts the work to its COM worker. No COM calls here.
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.Marshalling;

namespace PrismControl.Audio.Interop;

internal interface IAudioCallbackSink
{
    void OnDeviceListChanged();
    void OnDefaultChanged(EDataFlow flow, ERole role, string? deviceId);
    void OnDevicePropertyChanged(string deviceId, PROPERTYKEY key);
    void OnEndpointNotify(string deviceId, Guid context, bool muted, float volume);
    void OnSessionCreated(string deviceId);
    void OnSessionVolume(string sessionKey, float volume, bool muted, Guid context);
    void OnSessionState(string sessionKey, int state);
    void OnSessionNameChanged(string sessionKey);
    /// <summary>IAudioSessionEvents::OnSessionDisconnected; reason 1 (DisconnectReasonServerShutdown) means the audio service went away.</summary>
    void OnSessionDisconnected(string sessionKey, int reason);
}

[GeneratedComClass]
internal sealed partial class DeviceNotifications(IAudioCallbackSink sink) : IMMNotificationClient
{
    public int OnDeviceStateChanged(nint id, uint state) { sink.OnDeviceListChanged(); return 0; }
    public int OnDeviceAdded(nint id) { sink.OnDeviceListChanged(); return 0; }
    public int OnDeviceRemoved(nint id) { sink.OnDeviceListChanged(); return 0; }

    public int OnDefaultDeviceChanged(EDataFlow flow, ERole role, nint id)
    {
        sink.OnDefaultChanged(flow, role, id == 0 ? null : Marshal.PtrToStringUni(id));
        return 0;
    }

    public int OnPropertyValueChanged(nint id, PROPERTYKEY key)
    {
        if (id != 0 && (key.Is(PKeys.Device_FriendlyName) || key.Is(PKeys.Device_DeviceDesc) || key.Is(PKeys.DeviceInterface_FriendlyName)))
            sink.OnDevicePropertyChanged(Marshal.PtrToStringUni(id) ?? "", key);
        return 0;
    }
}

[GeneratedComClass]
internal sealed partial class EndpointVolumeCallback(IAudioCallbackSink sink, string deviceId) : IAudioEndpointVolumeCallback
{
    public unsafe int OnNotify(nint p)
    {
        if (p == 0) return 0;
        var ctx = *(Guid*)p;
        var muted = *(int*)(p + 16) != 0;
        var volume = *(float*)(p + 20);
        sink.OnEndpointNotify(deviceId, ctx, muted, volume);
        return 0;
    }
}

[GeneratedComClass]
internal sealed partial class SessionCreatedCallback(IAudioCallbackSink sink, string deviceId) : IAudioSessionNotification
{
    public int OnSessionCreated(nint s) { sink.OnSessionCreated(deviceId); return 0; }
}

[GeneratedComClass]
internal sealed partial class SessionEventsCallback(IAudioCallbackSink sink, string sessionKey) : IAudioSessionEvents
{
    public int OnDisplayNameChanged(nint a, nint b) { sink.OnSessionNameChanged(sessionKey); return 0; }
    public int OnIconPathChanged(nint a, nint b) => 0;

    public unsafe int OnSimpleVolumeChanged(float v, int m, nint c)
    {
        sink.OnSessionVolume(sessionKey, v, m != 0, c == 0 ? Guid.Empty : *(Guid*)c);
        return 0;
    }

    public int OnChannelVolumeChanged(uint n, nint a, uint ch, nint c) => 0;
    public int OnGroupingParamChanged(nint a, nint b) => 0;
    public int OnStateChanged(int s) { sink.OnSessionState(sessionKey, s); return 0; }
    public int OnSessionDisconnected(int r) { sink.OnSessionDisconnected(sessionKey, r); return 0; }
}
